head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf00600";
scwin.result = null;
scwin.v_str = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — loginYn, message

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.v_str = "" + dma_vo.get("reqDivCd") + "";
        scwin.init_conds();
        scwin.init_datefmt_cal_isuDd();
        scwin.init_datefmt_cal_listDd();
        scwin.init_datefmt_cal_redmptDd();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf00600.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_loginYn", fn: function(){ return ((dma_pageContext.get("loginYn") ?? "") === 'Y'); } }, { id: "if_loginYn_2", fn: function(){ return ((dma_pageContext.get("loginYn") ?? "") === 'N'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_datefmt_cal_isuDd
 * @description 초기화 — datefmt cal isu Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_isuDd = function () { $c.date.checkCalendarFormat("cal_isuDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_listDd
 * @description 초기화 — datefmt cal list Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_listDd = function () { $c.date.checkCalendarFormat("cal_listDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_redmptDd
 * @description 초기화 — datefmt cal redmpt Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_redmptDd = function () { $c.date.checkCalendarFormat("cal_redmptDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.showMessage();
        $c.util.getComponent("dma_feeCalcReq").set("redmptDd", $c.util.getComponent('cal_redmptDd').getValue());

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf00600.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    $c.util.getComponent("ipt_listFee").setValue("");
    $c.util.getComponent("ipt_listDutyRsn").setValue("");
    $c.util.getComponent("ipt_anulfee").setValue("");
    $c.util.getComponent("ipt_anulDutyRsn").setValue("");
};

