///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_feeCalc
 * @description fee Calc 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_feeCalc = async function (action) {
    const sbmOptions = {
        id: "tx_fn_feeCalc",
        method: "post",
        action: action ?? "/main/fee.do?method=feeCalc",
        ref: "dma_feeCalcReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_Chk_Mkt_Holdy_calc
 * @description Chk Mkt Holdy calc 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_Chk_Mkt_Holdy_calc = async function () {
    const sbmOptions = {
        id: "tx_Chk_Mkt_Holdy_calc",
        method: "post",
        action: "/common/common.do?method=checkMktHoldy_calc",
        ref: "dma_Chk_Mkt_HoldyCalcReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_print
 * @description print 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_print = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_printReq") ? $c.util.getComponent("dma_printReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_downloadFile_direct
 * @description download File direct 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_downloadFile_direct = async function (action) {
    try { return await $c.data.downFile(action ?? "/upload/downloadFile.do", "", ($c.util.getComponent("dma_downloadFileDirectReq") ? $c.util.getComponent("dma_downloadFileDirectReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name showMessage
 * @description show Message 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showMessage = async function () {
    const message = (String(((dma_pageContext.get("message") ?? "")) == null ? '' : ((dma_pageContext.get("message") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("message") ?? "")) == null ? '' : ((dma_pageContext.get("message") ?? ""))));
    await $c.win.alert(message);
};

/**
 * @method
 * @name setCurrUnit
 * @description set Curr Unit 처리
 * @param {String} currIsoCd currIsoCd
 * @returns {void}
 * @hidden N
 */
scwin.setCurrUnit = function (currIsoCd) {
    let currUnit = "";
    if (currIsoCd === "1") {
        currUnit = "원";
    } else {
        if (currIsoCd === "2") {
            currUnit = "달러";
        } else {
            if (currIsoCd === "3") {
                currUnit = "엔";
            } else {
                if (currIsoCd === "4") {
                    currUnit = "유로";
                } else {
                    if (currIsoCd === "5") {
                        currUnit = "위안";
                    }
                }
            }
        }
    }
    $c.util.getComponent("dma_feeCalcReq").set("currUnit", currUnit);
    $c.util.getComponent('dma_feeCalcReq').set('nCurrUnit', currUnit);
};

/**
 * @method
 * @name setListDd
 * @description set List Dd 처리
 * @param {String} cal_isuDd cal_isuDd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setListDd = async function (cal_isuDd) {
    if ((String($c.util.getComponent('ipt_setListDdYn').getValue() || "") !== "")) {
        if (cal_isuDd == null || cal_isuDd === "") {
            await $c.win.alert("발행일을 입력하시기 바랍니다.");
            $c.util.getComponent("ipt_setListDdYn").setValue(false);
            (cal_isuDd && cal_isuDd.setFocus ? $c.util.getComponent('cal_isuDd').setFocus() : (cal_isuDd && cal_isuDd.focus ? $c.util.getComponent("cal_isuDd").focus() : void 0));
            return;
        } else {
            if (cal_isuDd.length < 8) {
                await $c.win.alert("발행일이 유효하지 않습니다.");
                $c.util.getComponent("cal_listDd").setValue("");
                $c.util.getComponent("ipt_setListDdYn").setValue(false);
                (cal_isuDd && cal_isuDd.setFocus ? $c.util.getComponent('cal_isuDd').setFocus() : (cal_isuDd && cal_isuDd.focus ? $c.util.getComponent("cal_isuDd").focus() : void 0));
                return;
            }
        }
        $c.util.getComponent("cal_listDd").setValue(cal_isuDd);
    } else {
        $c.util.getComponent("cal_listDd").setValue("");
        $c.util.getComponent("cal_listDd").focus();
    }
};

/**
 * @method
 * @name setRedmptDd
 * @description set Redmpt Dd 처리
 * @param {String} cal_isuDd cal_isuDd
 * @param {*} addYy addYy
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setRedmptDd = async function (cal_isuDd, addYy) {
    const isuDdVal = cal_isuDd.replace(/-/g, '');
    const isuDdLen = isuDdVal.length;
    if (isuDdVal == null || isuDdVal === "") {
        await $c.win.alert("발행일을 입력하시기 바랍니다.");
        $c.util.getComponent("cal_isuDd").focus();
        return;
    } else {
        if (isuDdLen < 8) {
            await $c.win.alert("발행일이 유효하지 않습니다.");
            $c.util.getComponent("cal_isuDd").setValue("");
            $c.util.getComponent("cal_isuDd").focus();
            return;
        }
    }
    const tmpIsuDdYy = isuDdVal.substring(0, 4);
    const tmpIsuDdMm = isuDdVal.substring(4, 6);
    const tmpIsuDdDd = isuDdVal.substring(6, 8);
    const calcYear = parseInt(tmpIsuDdYy) + parseInt(addYy);
    const redmptDd = calcYear.toString() + '-' + tmpIsuDdMm + '-' + tmpIsuDdDd;
    $c.util.getComponent("dma_feeCalcReq").set("redmptDd", redmptDd);
};

/**
 * @method
 * @name setRedmptDdOld
 * @description set Redmpt Dd Old 처리
 * @param {String} cal_isuDd cal_isuDd
 * @param {*} addYy addYy
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setRedmptDdOld = async function (cal_isuDd, addYy) {
    const isuDdVal = cal_isuDd.replace(/-/g, '');
    const isuDdLen = isuDdVal.length;
    if (isuDdVal == null || isuDdVal === "") {
        await $c.win.alert("발행일을 입력하시기 바랍니다.");
        $c.util.getComponent("cal_isuDd").focus();
        return;
    } else {
        if (isuDdLen < 8) {
            await $c.win.alert("발행일이 유효하지 않습니다.");
            $c.util.getComponent("cal_isuDd").setValue("");
            $c.util.getComponent("cal_isuDd").focus();
            return;
        }
    }
    const tmpIsuDdYy = isuDdVal.substring(0, 4);
    const tmpIsuDdMm = isuDdVal.substring(4, 6);
    const tmpIsuDdDd = isuDdVal.substring(6, 8);
    const calcDate = $c.date.addMonth(tmpIsuDdYy, tmpIsuDdMm, tmpIsuDdDd, parseInt(addYy) * 12);
    const calcDateYy = calcDate.getFullYear().toString();
    const calcDateMm = (calcDate.getMonth() + 1).toString();
    const calcDateDd = calcDate.getDate().toString();
    const redmptDd = calcDateYy + '-' + fill(calcDateMm, 2, '0') + '-' + fill(calcDateDd, 2, '0');
    $c.util.getComponent("dma_feeCalcReq").set("redmptDd", redmptDd);
};

/**
 * @method
 * @name addDay
 * @description add Day 처리
 * @param {*} ymd ymd
 * @param {Number} cnt cnt
 * @param {*} buho buho
 * @returns {void}
 * @hidden N
 */
scwin.addDay = function (ymd, cnt, buho) {
    let real_ymd = ymd.replace('-', '');
    real_ymd = real_ymd.replace('-', '');
    let yyyy = real_ymd.substring(0, 4);
    let mm = (real_ymd.substring(4, 6) + '-1');
    let dd = real_ymd.substring(6, 8);
    const dt = new Date(yyyy, mm, (dd + buho + cnt));
    yyyy = dt.getYear();
    mm = (dt.getMonth() + 1) < 10 ? '0' + (dt.getMonth() + 1) : (dt.getMonth() + 1);
    dd = dt.getDate() < 10 ? '0' + (dt.getDate()) : (dt.getDate());
    return yyyy + '-' + mm + '-' + dd;
};

