// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name Chk_Mkt_Holdy_calc_done
 * @description Chk Mkt Holdy calc done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.Chk_Mkt_Holdy_calc_done = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_temp').setValue(scwin.result.sendResult);
};

/**
 * @method
 * @name Chk_Mkt_Holdy_calc
 * @description Chk Mkt Holdy calc 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.Chk_Mkt_Holdy_calc = async function () {
    const r = await scwin.tx_Chk_Mkt_Holdy_calc();
    try {
        scwin.Chk_Mkt_Holdy_calc_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldbnf00600.Chk_Mkt_Holdy_calc' });
    }
    return r;
};
